import pytesseract
from PIL import Image
import os
import re
import json
from datetime import datetime

def extract_date(text):
    # Common date patterns: DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY, YYYY/MM/DD, YYYY-MM-DD
    # Also DD/MM/YY etc.
    patterns = [
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})', # 28/01/2026 or 01-28-2026
        r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})', # 2026-01-28
        r'(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[a-z]*\s+(\d{2,4})', # 28 Jan 2026
    ]

    for pattern in patterns:
        matches = re.findall(pattern, text, re.IGNORECASE)
        for match in matches:
            try:
                if len(match[0]) == 4: # YYYY-MM-DD
                    y, m, d = int(match[0]), int(match[1]), int(match[2])
                elif int(match[2]) > 31: # DD/MM/YYYY
                    d, m, y = int(match[0]), int(match[1]), int(match[2])
                else: # Could be MM/DD/YY or DD/MM/YY. Usually receipts are DD/MM/YY in many regions, 
                      # but let's try to be smart or just pick the first valid one.
                    d, m, y = int(match[0]), int(match[1]), int(match[2])
                    if y < 100: y += 2000
                    if m > 12: # Swap if it looks like MM/DD/YY
                        m, d = d, m

                if 1 <= m <= 12 and 1 <= d <= 31:
                    return f"{y:04d}-{m:02d}-{d:02d}"
            except:
                continue
    return None

def extract_total(text):
    lines = text.split('\n')

    keywords = [
        'GRAND TOTAL',
        'TOTAL RM', 'TOTAL: RM',
        'TOTAL AMOUNT',
        'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'
    ]

    exclusion_keywords = [
        'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
    ]

    amount_pattern = r'(\d{1,3}(?:,\d{3})*\.\d{2})'

    results = []

    for i, line in enumerate(lines):
        upper_line = line.upper()

        # Check for exclusion keywords
        if any(excl in upper_line for excl in exclusion_keywords):
            continue

        for kw in keywords:
            if kw in upper_line:
                # Try to find amount on the same line
                amounts = re.findall(amount_pattern, line)
                if amounts:
                    # Take the last amount on the line as it's more likely to be the total
                    results.append((kw, amounts[-1]))
                    break
                # Fallback to next line
                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    next_amounts = re.findall(amount_pattern, next_line)
                    if next_amounts:
                        results.append((kw, next_amounts[-1]))
                        break

    if not results:
        return None

    # Priority based on keyword order
    for kw in keywords:
        for res_kw, res_val in results:
            if kw == res_kw:
                return res_val.replace(',', '')

    # If no priority match, return the first one found
    return results[0][1].replace(',', '')

def main():
    img_dir = 'dataset/img'
    files = sorted([f for f in os.listdir(img_dir) if f.endswith('.jpg')])

    all_results = []

    for filename in files:
        img_path = os.path.join(img_dir, filename)
        try:
            text = pytesseract.image_to_string(Image.open(img_path))

            date = extract_date(text)
            total = extract_total(text)

            # Format total to exactly two decimal places if it's a number
            if total:
                try:
                    total = "{:.2f}".format(float(total))
                except:
                    total = None

            all_results.append({
                "filename": filename,
                "date": date,
                "total_amount": total
            })
        except Exception as e:
            all_results.append({
                "filename": filename,
                "date": None,
                "total_amount": None
            })

    print(json.dumps(all_results))

if __name__ == "__main__":
    main()

